create table public.food_categories(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null unique,description text,display_order integer not null default 0 check(display_order>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.foods(id uuid primary key default gen_random_uuid(),category_id uuid references public.food_categories(id) on delete set null,slug text not null unique,name text not null,brand_name text,description text,common_aliases text[] not null default '{}',source_type text not null default 'curated' check(source_type in('curated','external_provider','manufacturer','other')),source_reference text,is_verified boolean not null default false,is_active boolean not null default true,is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(char_length(btrim(name)) between 2 and 160));
create table public.food_servings(id uuid primary key default gen_random_uuid(),food_id uuid not null references public.foods(id) on delete cascade,serving_name text not null,serving_quantity numeric not null check(serving_quantity>0),serving_unit text not null,grams_equivalent numeric check(grams_equivalent>0),calories numeric check(calories>=0),protein_grams numeric check(protein_grams>=0),carbohydrate_grams numeric check(carbohydrate_grams>=0),fat_grams numeric check(fat_grams>=0),fiber_grams numeric check(fiber_grams>=0),sugar_grams numeric check(sugar_grams>=0),sodium_mg numeric check(sodium_mg>=0),caffeine_mg numeric check(caffeine_mg>=0),alcohol_grams numeric check(alcohol_grams>=0),is_default boolean not null default false,display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index food_servings_one_default_idx on public.food_servings(food_id) where is_default;
create table public.user_foods(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(btrim(name)) between 2 and 160),brand_name text,description text,serving_name text not null,serving_quantity numeric not null check(serving_quantity>0),serving_unit text not null,grams_equivalent numeric check(grams_equivalent>0),calories numeric check(calories>=0),protein_grams numeric check(protein_grams>=0),carbohydrate_grams numeric check(carbohydrate_grams>=0),fat_grams numeric check(fat_grams>=0),fiber_grams numeric check(fiber_grams>=0),sugar_grams numeric check(sugar_grams>=0),sodium_mg numeric check(sodium_mg>=0),caffeine_mg numeric check(caffeine_mg>=0),alcohol_grams numeric check(alcohol_grams>=0),is_favorite boolean not null default false,is_active boolean not null default true,last_logged_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,unique(id,user_id),check(num_nonnulls(calories,protein_grams,carbohydrate_grams,fat_grams,fiber_grams,sugar_grams,sodium_mg,caffeine_mg,alcohol_grams)>=1));
create table public.nutrition_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,entry_type text not null default 'food' check(entry_type in('food','meal','snack','beverage','other')),meal_type text check(meal_type in('breakfast','lunch','dinner','snack','other')),title text,consumed_at timestamptz not null,source_type text not null default 'manual' check(source_type in('manual','quick_add','import','other')),notes text check(notes is null or char_length(notes)<=2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(id,user_id));
create table public.nutrition_entry_items(id uuid primary key default gen_random_uuid(),nutrition_entry_id uuid not null references public.nutrition_entries(id) on delete cascade,food_id uuid references public.foods(id) on delete set null,food_serving_id uuid references public.food_servings(id) on delete set null,user_food_id uuid references public.user_foods(id) on delete set null,source_name text not null,source_brand_name text,serving_name_snapshot text not null,serving_quantity_snapshot numeric not null check(serving_quantity_snapshot>0),serving_unit_snapshot text not null,quantity_multiplier numeric not null default 1 check(quantity_multiplier>0),grams_consumed numeric check(grams_consumed>=0),calories numeric check(calories>=0),protein_grams numeric check(protein_grams>=0),carbohydrate_grams numeric check(carbohydrate_grams>=0),fat_grams numeric check(fat_grams>=0),fiber_grams numeric check(fiber_grams>=0),sugar_grams numeric check(sugar_grams>=0),sodium_mg numeric check(sodium_mg>=0),caffeine_mg numeric check(caffeine_mg>=0),alcohol_grams numeric check(alcohol_grams>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((food_id is not null and food_serving_id is not null and user_food_id is null) or (food_id is null and food_serving_id is null and user_food_id is not null)));
create index foods_active_category_name_idx on public.foods(category_id,name) where is_active;create index foods_name_idx on public.foods(lower(name));create index food_servings_food_idx on public.food_servings(food_id,display_order);create index user_foods_user_recent_idx on public.user_foods(user_id,last_logged_at desc) where is_active and archived_at is null;create index nutrition_entries_user_day_idx on public.nutrition_entries(user_id,consumed_at desc) where deleted_at is null;create index nutrition_entry_items_entry_idx on public.nutrition_entry_items(nutrition_entry_id);
do $$declare t text;begin foreach t in array array['food_categories','foods','food_servings','user_foods','nutrition_entries','nutrition_entry_items'] loop execute format('create trigger %I before update on public.%I for each row execute function public.axvital_planning_set_updated_at()',t||'_set_updated_at',t);execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "Authenticated users read food categories" on public.food_categories for select to authenticated using(is_active);create policy "Authenticated users read foods" on public.foods for select to authenticated using(is_active);create policy "Authenticated users read food servings" on public.food_servings for select to authenticated using(exists(select 1 from public.foods f where f.id=food_id and f.is_active));
create policy "Users manage own foods" on public.user_foods for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "Users manage own nutrition entries" on public.nutrition_entries for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "Users manage own nutrition items" on public.nutrition_entry_items for all to authenticated using(exists(select 1 from public.nutrition_entries e where e.id=nutrition_entry_id and e.user_id=(select auth.uid()))) with check(exists(select 1 from public.nutrition_entries e where e.id=nutrition_entry_id and e.user_id=(select auth.uid())));
create function public.log_food_atomic(selected_food_id uuid,selected_serving_id uuid,selected_user_food_id uuid,quantity numeric,consumed timestamptz,meal text default null,note text default null,entry_source text default 'manual') returns uuid language plpgsql security invoker set search_path='' as $$declare u uuid:=(select auth.uid());e uuid;s record;begin if u is null or quantity<=0 or ((selected_user_food_id is null)=(selected_food_id is null)) then raise exception 'Invalid food log';end if;if selected_user_food_id is not null then select id,name,brand_name,serving_name,serving_quantity,serving_unit,grams_equivalent,calories,protein_grams,carbohydrate_grams,fat_grams,fiber_grams,sugar_grams,sodium_mg,caffeine_mg,alcohol_grams into s from public.user_foods where id=selected_user_food_id and user_id=u and is_active and archived_at is null;else select f.id,f.name,f.brand_name,fs.serving_name,fs.serving_quantity,fs.serving_unit,fs.grams_equivalent,fs.calories,fs.protein_grams,fs.carbohydrate_grams,fs.fat_grams,fs.fiber_grams,fs.sugar_grams,fs.sodium_mg,fs.caffeine_mg,fs.alcohol_grams into s from public.foods f join public.food_servings fs on fs.food_id=f.id where f.id=selected_food_id and fs.id=selected_serving_id and f.is_active;end if;if s.id is null then raise exception 'Food not found';end if;insert into public.nutrition_entries(user_id,title,consumed_at,meal_type,notes,source_type)values(u,s.name,consumed,meal,note,entry_source)returning id into e;insert into public.nutrition_entry_items(nutrition_entry_id,food_id,food_serving_id,user_food_id,source_name,source_brand_name,serving_name_snapshot,serving_quantity_snapshot,serving_unit_snapshot,quantity_multiplier,grams_consumed,calories,protein_grams,carbohydrate_grams,fat_grams,fiber_grams,sugar_grams,sodium_mg,caffeine_mg,alcohol_grams)values(e,selected_food_id,selected_serving_id,selected_user_food_id,s.name,s.brand_name,s.serving_name,s.serving_quantity,s.serving_unit,quantity,s.grams_equivalent*quantity,s.calories*quantity,s.protein_grams*quantity,s.carbohydrate_grams*quantity,s.fat_grams*quantity,s.fiber_grams*quantity,s.sugar_grams*quantity,s.sodium_mg*quantity,s.caffeine_mg*quantity,s.alcohol_grams*quantity);if selected_user_food_id is not null then update public.user_foods set last_logged_at=consumed where id=selected_user_food_id and user_id=u;end if;return e;end$$;grant execute on function public.log_food_atomic(uuid,uuid,uuid,numeric,timestamptz,text,text,text) to authenticated;
