,inserted as(insert into public.foods(category_id,slug,name,common_aliases,is_featured)select c.id,s.slug,s.name,s.aliases,true from seed s join public.food_categories c on c.slug=s.category_slug on conflict(slug)do update set name=excluded.name returning id,slug)
insert into public.food_servings(food_id,serving_name,serving_quantity,serving_unit,grams_equivalent,calories,protein_grams,carbohydrate_grams,fat_grams,is_default)select f.id,s.serving_name,s.qty,s.unit,s.grams,s.calories,s.protein,s.carbs,s.fat,true from seed s join public.foods f on f.slug=s.slug where not exists(select 1 from public.food_servings fs where fs.food_id=f.id and fs.is_default);
